local SutureMaker = {}
local PRODUCTS = {
    iron_suture = { name = "Zelezna siva", ironCost = 1, leatherCost = 2, woodCost = 1, time = 4, cost = 130, prestige = 2, happiness = 1, description = "Zelezna siva za zapiranje ran." },
    bronze_suture = { name = "Bronasta siva", bronzeCost = 1, ironCost = 1, leatherCost = 2, woodCost = 1, time = 6, cost = 320, prestige = 4, happiness = 2, description = "Bronasta siva za kirurske rane." },
    silver_suture = { name = "Srebrna siva", silverCost = 1, bronzeCost = 1, ironCost = 1, leatherCost = 1, woodCost = 1, time = 10, cost = 760, prestige = 9, happiness = 3, description = "Srebrna siva za plemiske zdravnike." },
    gilded_suture = { name = "Pozlacena siva", goldCost = 1, silverCost = 1, bronzeCost = 1, leatherCost = 1, woodCost = 1, time = 14, cost = 1620, prestige = 17, happiness = 4, description = "Pozlacena siva za dvornega kirurga." },
    jewel_set_suture = { name = "Draguljasta siva", goldCost = 2, silverCost = 1, jewelCost = 1, bronzeCost = 1, leatherCost = 1, woodCost = 1, time = 18, cost = 3500, prestige = 32, happiness = 6, description = "Draguljasta siva za kraljevega zdravnika." },
    royal_sovereign_suture = { name = "Kraljevski suverena siva", goldCost = 3, silverCost = 2, jewelCost = 2, pearlCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 24, cost = 7400, prestige = 64, happiness = 11, description = "Suverena siva z biseri za krono." },
}
local BUILDINGS = {
    suture_workshop = { name = "Sivarska delavnica", cost = { gold = 320, wood = 160, stone = 120, iron = 6 }, upkeep = 6, qualityBonus = 5 },
    suture_house = { name = "Sivarska hisa", cost = { gold = 1140, wood = 340, stone = 250, silver = 6, iron = 6 }, upkeep = 24, qualityBonus = 18 },
    master_suture_atelier = { name = "Mojstrski sivarski atelje", cost = { gold = 2850, wood = 400, stone = 490, silver = 32, gold = 6 }, upkeep = 66, qualityBonus = 30 },
    sovereign_surgical_palace = { name = "Suverena kirurska palaca", cost = { gold = 12000, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 238, qualityBonus = 55, prestigeBonus = 55 },
}
SutureMaker.ironStock = 12; SutureMaker.bronzeStock = 10; SutureMaker.woodStock = 14; SutureMaker.leatherStock = 10; SutureMaker.silverStock = 8; SutureMaker.goldStock = 6; SutureMaker.jewelStock = 4; SutureMaker.pearlStock = 4
SutureMaker.productStock = {}; SutureMaker.buildings = {}; SutureMaker.maker = nil; SutureMaker.activeMaking = {}; SutureMaker.totalProducts = 0; SutureMaker.dayTimer = 0
function SutureMaker.init() SutureMaker.ironStock=12; SutureMaker.bronzeStock=10; SutureMaker.woodStock=14; SutureMaker.leatherStock=10; SutureMaker.silverStock=8; SutureMaker.goldStock=6; SutureMaker.jewelStock=4; SutureMaker.pearlStock=4; SutureMaker.productStock={}; SutureMaker.buildings={}; SutureMaker.maker=nil; SutureMaker.activeMaking={}; SutureMaker.totalProducts=0; SutureMaker.dayTimer=0; print("[SutureMaker] Royal Suture Maker System initialized (6 products, 4 buildings)") end
function SutureMaker.hireMaker(n,s) s=s or math.random(55,90); local c=560+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SutureMaker.maker={name=n or ("Sivalec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sivalec najet: %s (spretnost: %d)",SutureMaker.maker.name,s),"success") end; return true end
function SutureMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SutureMaker.build(id) local ok,e=SutureMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SutureMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SutureMaker.getQualityBonus() local b=0; for _,bd in ipairs(SutureMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SutureMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and SutureMaker.ironStock<(d.ironCost or 0) then return false,"Premalo zeleza" end; if d.bronzeCost and SutureMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and SutureMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and SutureMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and SutureMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SutureMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SutureMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SutureMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SutureMaker.buildings==0 then return false,"Potrebna delavnica" end; if not SutureMaker.maker then return false,"Potreben mojster" end; return true end
function SutureMaker.make(pt,qty) qty=qty or 1; local ok,e=SutureMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then SutureMaker.ironStock=SutureMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then SutureMaker.bronzeStock=SutureMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then SutureMaker.woodStock=SutureMaker.woodStock-d.woodCost*qty end; if d.leatherCost then SutureMaker.leatherStock=SutureMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then SutureMaker.silverStock=SutureMaker.silverStock-d.silverCost*qty end; if d.goldCost then SutureMaker.goldStock=SutureMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SutureMaker.jewelStock=SutureMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SutureMaker.pearlStock=SutureMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SutureMaker.maker then t=math.max(1,t-math.floor(SutureMaker.maker.skill/13)) end; table.insert(SutureMaker.activeMaking,{id="suture_"..tostring(os.time()).."_a"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SutureMaker.completeMaking(m) local q=1.0+(SutureMaker.getQualityBonus()/100); if SutureMaker.maker then q=q+(SutureMaker.maker.skill/140) end; q=math.min(2.5,q); SutureMaker.productStock[m.productType]=(SutureMaker.productStock[m.productType] or 0)+m.quantity; SutureMaker.totalProducts=SutureMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SutureMaker.maker then SutureMaker.maker.itemsMade=SutureMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SutureMaker.maker.skill=math.min(100,SutureMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"suture.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function SutureMaker.update(dt) if not _G.state then return end; SutureMaker.dayTimer=SutureMaker.dayTimer+dt; if SutureMaker.dayTimer>=30 then SutureMaker.dayTimer=0; for i=#SutureMaker.activeMaking,1,-1 do local m=SutureMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SutureMaker.completeMaking(m); table.remove(SutureMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SutureMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SutureMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SutureMaker.getStats() return {ironStock=SutureMaker.ironStock,bronzeStock=SutureMaker.bronzeStock,woodStock=SutureMaker.woodStock,leatherStock=SutureMaker.leatherStock,silverStock=SutureMaker.silverStock,goldStock=SutureMaker.goldStock,jewelStock=SutureMaker.jewelStock,pearlStock=SutureMaker.pearlStock,productStock=SutureMaker.productStock,numBuildings=#SutureMaker.buildings,hasMaker=SutureMaker.maker~=nil,makerName=SutureMaker.maker and SutureMaker.maker.name or "Â",makerSkill=SutureMaker.maker and SutureMaker.maker.skill or 0,activeMaking=#SutureMaker.activeMaking,totalProducts=SutureMaker.totalProducts} end
return SutureMaker
